TypeScript example:
import { createEventStream } from '@redwood/sdk';
const stream = createEventStream({ model: 'gpt-compatible', structured: true });
for await (const evt of stream) {
  // evt.event_type === 'delta' | 'tool_invocation' | 'structured_chunk'
  if (evt.event_type === 'delta') process.stdout.write(evt.payload.text);
  if (evt.event_type === 'tool_invocation') {
    // sdk helper to call a tool
    const res = await sdk.tools.invoke(evt.payload.tool_name, evt.payload.args, { invocationId: evt.payload.invocation_id });
    stream.sendToRuntime({ event_type: 'tool_result', invocation_id: evt.payload.invocation_id, result: res });
  }
  if (evt.event_type === 'structured_chunk') assembler.push(evt.payload);
}
// assembler.finalize() yields the complete typed object

Go example:
stream, err := sdk.NewEventStream(ctx, sdk.Config{Model: "gpt-compatible", Structured: true})
if err != nil { log.Fatal(err) }
for ev := range stream.Ch {
  switch ev.Type {
  case sdk.EventDelta:
    fmt.Print(ev.Payload.Text)
  case sdk.EventToolInvocation:
    go func(e sdk.Event) {
      res := callToolSync(e.Payload.ToolName, e.Payload.Args)
      stream.Send(sdk.Event{Type: sdk.EventToolResult, Payload: map[string]interface{}{"invocation_id": e.Payload.InvocationID, "result": res}})
    }(ev)
  case sdk.EventStructuredChunk:
    assembler.Push(ev.Payload)
  }
}
